package evidence

import (
	"fmt"
	"math/rand"
	"testing"

	"evicon/internal/analyzer"
	"evicon/internal/domain"
	"evicon/internal/journal"
)

// TestProductFormMatchesEnumeration (release 072): for random ADD-only
// histories, the relational guard over the product-form belief gives the same
// verdict as over the enumerated (reachability-closed) belief. This is the
// executable check of the paper's Lemma "product form" and of Theorem 3's
// reservation form. Histories are generated by safe admissions, as in the
// runtime; mismatched generations/epochs and STOPPED commands are included.
func TestProductFormMatchesEnumeration(t *testing.T) {
	rng := rand.New(rand.NewSource(20261021))
	cases, admits, blocks := 0, 0, 0
	for cases < 10000 {
		dim := 1 + rng.Intn(2)
		anchor := make([]int64, dim)
		maxs := make([]int64, dim)
		mins := make([]int64, dim)
		for i := range anchor {
			anchor[i] = int64(rng.Intn(5))
			maxs[i] = anchor[i] + int64(5+rng.Intn(20))
		}
		var sum *int64
		if dim == 2 && rng.Intn(2) == 0 {
			s := anchor[0] + anchor[1] + int64(8+rng.Intn(20))
			sum = &s
		}
		bound := domain.HardBound{ComponentMin: mins, ComponentMax: maxs, SumMax: sum}
		d := journal.Domain{Generation: 1, Dimension: dim, InstalledEpoch: 1, Anchor: anchor}
		registry := map[string]domain.Command{}
		known := map[string]domain.CommandStatus{}
		k := rng.Intn(6)
		for j := 0; j < k; j++ {
			v := make([]int64, dim)
			for i := range v {
				v[i] = int64(rng.Intn(5))
			}
			id := fmt.Sprintf("c%d", j)
			cmd := domain.Command{ID: id, Generation: 1, Epoch: 1, Sequence: uint64(j + 1), Operation: domain.OpAdd, Value: v}
			if rng.Intn(10) == 0 {
				cmd.Epoch = 2 // can never apply in this configuration
			}
			// keep the history safe: admit only what the enumerated guard admits
			if b, _, ok, err := BuildAddOnlyReducedBeliefExact(1, dim, 1, 0, anchor, registry, known, 1<<20); ok && err == nil {
				if r, err := analyzer.RelationalGuard(b, cmd, bound); err != nil || r.Verdict != analyzer.Safe {
					continue
				}
			}
			registry[id] = cmd
			switch rng.Intn(3) {
			case 0:
				if cmd.Epoch == 1 {
					known[id] = domain.Applied
				}
			case 1:
				known[id] = domain.Stopped
			}
		}
		cv := make([]int64, dim)
		for i := range cv {
			cv[i] = int64(rng.Intn(8))
		}
		cand := domain.Command{ID: "cand", Generation: 1, Epoch: 1, Sequence: uint64(k + 1), Operation: domain.OpAdd, Value: cv}
		enum, _, ok, err := BuildAddOnlyReducedBeliefExact(1, dim, 1, 0, anchor, registry, known, 1<<20)
		if !ok || err != nil {
			continue // model inconsistency (e.g. applied + mismatched epoch) is handled identically by both builders
		}
		prod, st, ok, err := buildAddOnlyProductBelief(d, registry, known, 256)
		if !ok || err != nil {
			t.Fatalf("product form not applicable: ok=%v err=%v", ok, err)
		}
		if len(prod.Configurations) != 1 || st.Algorithm != "add_only_product_v1" {
			t.Fatalf("unexpected product belief: %d configs, %s", len(prod.Configurations), st.Algorithm)
		}
		re, err1 := analyzer.RelationalGuard(enum, cand, bound)
		rp, err2 := analyzer.RelationalGuard(prod, cand, bound)
		if err1 != nil || err2 != nil {
			t.Fatalf("guard errors: %v %v", err1, err2)
		}
		if re.Verdict != rp.Verdict {
			t.Fatalf("case %d: enumerated %s (%s, %d configs) vs product %s (%s); registry=%v known=%v cand=%v bound=%+v",
				cases, re.Verdict, re.Reason, len(enum.Configurations), rp.Verdict, rp.Reason, registry, known, cand.Value, bound)
		}
		if re.Verdict == analyzer.Safe {
			admits++
		} else {
			blocks++
		}
		cases++
	}
	if admits < 1000 || blocks < 1000 {
		t.Fatalf("weak coverage: %d admits, %d blocks", admits, blocks)
	}
}

// TestProductFormHasNoConfigurationCap (release 072): many unresolved ADDs
// no longer exhaust the configuration budget; the window is max_outstanding.
func TestProductFormHasNoConfigurationCap(t *testing.T) {
	d := journal.Domain{Generation: 1, Dimension: 1, InstalledEpoch: 1, Anchor: []int64{0}}
	var cmds []journal.CommandRecord
	for j := 0; j < 40; j++ {
		cmds = append(cmds, journal.CommandRecord{CommandID: fmt.Sprintf("c%d", j), Generation: 1, Epoch: 1, Sequence: uint64(j + 1), Operation: domain.OpAdd, Value: []int64{1}, Status: "ADMITTED"})
	}
	b, st, err := BuildBeliefWithStats(d, cmds, 256)
	if err != nil {
		t.Fatalf("40 unresolved ADDs: %v", err)
	}
	if len(b.Configurations) != 1 || st.Algorithm != "add_only_product_v1" {
		t.Fatalf("want one product configuration, got %d (%s)", len(b.Configurations), st.Algorithm)
	}
	// a SET keeps the enumerated belief and its cap
	cmds = append(cmds, journal.CommandRecord{CommandID: "s", Generation: 1, Epoch: 1, Sequence: 41, Operation: domain.OpSet, Value: []int64{3}, Status: "ADMITTED"})
	if _, _, err := BuildBeliefWithStats(d, cmds, 256); err == nil {
		t.Fatalf("SET history with 41 pending commands should exceed the 256-configuration cap")
	}
}
